// Extrae los datos del body del webhook
const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    nombre:     body.nombre || '',
    email:      body.email  || '',
    perfil:     body.perfil || '',
    // Nuevos campos estructurados (opcionales)
    rol:        body.rol_objetivo || '',
    stack:      Array.isArray(body.stack) ? body.stack : (body.stack ? [body.stack] : []),
    salario:    parseInt(body.salario_min) || 0,
    modalidad:  Array.isArray(body.modalidad) ? body.modalidad : (body.modalidad ? [body.modalidad] : []),
    ciudad:     body.ciudad || '',
    linkedin:   body.linkedin || '',
    cv_master_url: body.cv_master_url || ''
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  parent: { database_id: '34811515f4b280f19a42f8da5e91a8fe' },
  properties: {
    Name:       { title:     [{ text: { content: $json.nombre } }] },
    Email:      { email:     $json.email },
    Perfil:     { rich_text: [{ text: { content: $json.perfil } }] },
    Activo:     { checkbox:  true },
    'Rol objetivo': { rich_text: [{ text: { content: $json.rol || '' } }] },
    Stack:      { multi_select: ($json.stack || []).map(s => ({ name: s })) },
    'Salario min': { number: $json.salario || null },
    Modalidad:  { multi_select: ($json.modalidad || []).map(m => ({ name: m })) },
    Ciudad:     { rich_text: [{ text: { content: $json.ciudad || '' } }] },
    LinkedIn:   { url:       $json.linkedin || null },
    'CV Master URL': { url: $json.cv_master_url || null }
  }
}) }}

